INSERT INTO projects (slug, kind, title, client, category, status, summary, description, features, stack, live_url, video, poster, aspect, seo_title, seo_description, featured, sort) VALUES ('watch-trade-chronicles', 'website', 'Watch Trade Chronicles', 'Watch Trade Chronicles', 'E-commerce', 'live', 'An online store for a watch reseller in Beirut, with a full admin dashboard behind it.', 'Watch Trade Chronicles sells pre-owned luxury watches. Appify designed and built the whole store: the catalogue and collections, a Strap Studio where buyers try straps on a watch before they order, and the admin side the team runs the business from: orders, inventory, sales analytics, review moderation and team accounts. We also made the launch film.', '["Product catalogue and collections", "Strap Studio: try straps on a watch before buying", "Orders, inventory and sales analytics", "Customer reviews, moderated before they go live", "Team accounts with invite links"]', '["Next.js", "React", "Cloudflare Workers", "D1 database", "Tailwind", "Framer Motion"]', 'https://watchtradechronicles.com', '/media/wtc-launch.mp4', '/media/wtc-launch.webp', '16/9', 'Watch Trade Chronicles: e-commerce website by Appify', 'Case study: an online watch store in Beirut with a Strap Studio, admin dashboard, inventory and sales analytics. Designed and built by Appify.', 1, 1);
INSERT INTO projects (slug, kind, title, client, category, status, summary, description, features, stack, live_url, video, poster, aspect, seo_title, seo_description, featured, sort) VALUES ('firnlight', 'website', 'Firnlight', 'Concept brand', 'Animated website', 'concept', 'A product site that plays like a film: your scroll scrubs a 466-frame sequence while the specs animate in.', 'Firnlight is a concept brand we designed and built to show what a scroll-driven product page can do. The scroll bar is the timeline: 466 rendered frames play as you move, the specs animate in on cue, macro detail shots take over the screen, and add-to-cart is built into the experience instead of bolted on at the end.', '["Scroll-scrubbed 466-frame product film", "Specs that animate in on cue", "Macro detail shots", "Add to cart built into the page"]', '["Vite", "JavaScript", "Lenis smooth scroll"]', 'https://omarnaous.github.io/firnlight/', '/media/firnlight.mp4', '/media/firnlight.webp', '4/5', 'Firnlight: scroll-driven animated product website (concept) by Appify', 'A concept product website where scrolling plays a 466-frame film, specs animate in and add-to-cart is part of the story. Designed and built by Appify.', 1, 2);
INSERT INTO projects (slug, kind, title, client, category, status, summary, description, features, stack, live_url, video, poster, aspect, seo_title, seo_description, featured, sort) VALUES ('oddball', 'website', 'Oddball', 'Concept brand', 'Animated website', 'concept', 'A basketball brand site with a 3D mascot that actually plays, cards that flip and light that follows your scroll.', 'Oddball is Animated Website 01 in our series: a concept basketball brand built to feel like a game day. A 3D mascot dunks on the hero, no two player cards look alike, light follows the scroll, the roster flips in 3D, the playbook animates, and even the sign-up form stays on brand.', '["3D mascot in the hero", "Player cards that flip in 3D", "Scroll-reactive lighting", "Animated playbook section", "On-brand forms"]', '[]', NULL, '/media/oddball.mp4', '/media/oddball.webp', '4/5', 'Oddball: animated 3D basketball website (concept) by Appify', 'Animated Website 01: a concept basketball brand with a 3D mascot, flipping roster cards and a scroll-driven playbook. Designed and built by Appify.', 1, 3);
INSERT INTO projects (slug, kind, title, client, category, status, summary, description, features, stack, live_url, video, poster, aspect, seo_title, seo_description, featured, sort) VALUES ('valmora', 'website', 'Valmora', 'Concept marque', 'Animated website', 'concept', 'A classic grand tourer, unveiled as you scroll: the cover comes off, the details get close-ups and a live gauge reads out the specs.', 'Valmora is Animated Website 02: a concept car marque. The car sits under a cover until you scroll it off, the hero is staged like a launch event, the crystal headlamps, wire wheels and quilted cabin each get their own close-up, a working gauge reads out the specs, and the private-viewing invitation form matches the rest of the brand. The car, specifications and imagery are illustrative.', '["Scroll-driven cover reveal", "Detail close-ups with callouts", "Live speedometer spec readout", "Private-viewing invitation form"]', '[]', NULL, '/media/valmora.mp4', '/media/valmora.webp', '4/5', 'Valmora: luxury car website with scroll reveal (concept) by Appify', 'Animated Website 02: a concept classic-car marque with a scroll-driven unveil, detail close-ups and a live spec gauge. Designed and built by Appify.', 1, 4);
INSERT INTO projects (slug, kind, title, client, category, status, summary, description, features, stack, live_url, video, poster, aspect, seo_title, seo_description, featured, sort) VALUES ('earshot', 'website', 'Earshot', 'Concept brand', 'Animated website', 'concept', 'It looks like a video game, but it''s a website: a fennec fox runs through four worlds as you scroll.', 'Earshot is Animated Website 03: a concept site where the hero never stops running. A fennec fox crosses four worlds (Mirage Miles, Pack Light, Tide Runs and Aurora Relay) and each world brings its own headline, colours and call to action, so the page feels like levels in a game.', '["Four scroll-driven worlds", "Continuous character animation", "Per-world colour and copy", "Game-style navigation"]', '[]', NULL, '/media/earshot.mp4', '/media/earshot.webp', '4/5', 'Earshot: game-style animated website (concept) by Appify', 'Animated Website 03: a concept website that plays like a video game, with a fox running through four scroll-driven worlds. Designed and built by Appify.', 1, 5);
INSERT INTO projects (slug, kind, title, client, category, status, summary, description, features, stack, live_url, video, poster, aspect, seo_title, seo_description, featured, sort) VALUES ('darebni-ai', 'app', 'Darebni AI', 'Darebni AI', 'Mobile app', 'in-development', 'An AI-powered fitness app, in development.', 'Darebni AI is an AI-powered fitness app Appify is building. Screens and store links will be added here at launch.', '[]', '[]', NULL, NULL, NULL, '9/19.5', NULL, NULL, 1, 6);
INSERT INTO motion (slug, title, client, kind, summary, video, poster, aspect, duration, upload_date, sort) VALUES ('balloon', 'The 7-second balloon', 'Appify', 'ad', 'A 3D balloon with our logo is pumped up toward a needle and pops into confetti at exactly 7 seconds. Built to hold attention, then prove it.', '/media/balloon.mp4', '/media/balloon.webp', '9/16', 14, '2026-10-14', 1);
INSERT INTO motion (slug, title, client, kind, summary, video, poster, aspect, duration, upload_date, sort) VALUES ('showreel', 'Appify showreel', 'Appify', 'brand', 'Nine motion styles in one reel: kinetic type, product shots, 3D, data and character animation.', '/media/showreel.mp4', '/media/showreel.webp', '9/16', 23, '2026-10-14', 2);
INSERT INTO motion (slug, title, client, kind, summary, video, poster, aspect, duration, upload_date, sort) VALUES ('ecommerce-chat', '“Hey Appify, I want an e-commerce website”', 'Appify', 'ad', 'A chat-style hook into a 7-day build, the price and a comparison table against subscription stores.', '/media/ecommerce-chat.mp4', '/media/ecommerce-chat.webp', '9/16', 24, '2026-10-14', 3);
