INSERT INTO motion (slug, title, client, kind, summary, video, poster, aspect, duration, upload_date, sort) VALUES ('photos-get-scrolled', '“Photos get scrolled”', 'Appify', 'reel', 'A mascot-led Instagram reel: a meme crash-zoom, a real case study and a real stat, with a synthesized soundtrack.', '/media/photos-get-scrolled.mp4', '/media/photos-get-scrolled.webp', '9/16', 50, '2026-10-14', 6);
