INSERT INTO motion (slug, title, client, kind, summary, video, poster, aspect, duration, upload_date, sort) VALUES ('logo-reveal', 'Logo reveal', 'Appify', 'brand', 'A spark falls onto a home screen, becomes an app icon and lands as the dot on the i.', '/media/logo-reveal.mp4', '/media/logo-reveal.webp', '4/5', 9, '2026-10-14', 9);
