INSERT INTO motion (slug, title, client, kind, summary, video, poster, aspect, duration, upload_date, sort) VALUES ('wtc-launch', 'Website launch film', 'Watch Trade Chronicles', 'client', 'A 25-second launch film for a watch store''s new website: kinetic type, animated counters, a strap try-on and a logo reveal.', '/media/wtc-launch.mp4', '/media/wtc-launch.webp', '16/9', 25, '2026-10-14', 11);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('websites', 'How much does a website cost in Lebanon with Appify?', 'Our lifetime website is $360, paid once. It includes the UI/UX design, an admin panel, custom analytics, motion graphics and free hosting, with no monthly subscription. Animated websites like the ones in our portfolio start from $500. Send us what you need and we''ll confirm the price before we start.', 1);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('websites', 'How long does it take to build a website?', 'We deliver websites in under 7 days. Bigger projects, like an online store with a large catalogue or custom features, get a timeline agreed with you before we start.', 2);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('websites', 'Are there monthly fees?', 'No. You pay once and the website is yours. Hosting is included, so there''s no monthly subscription to keep it online.', 3);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('websites', 'Do I own my website and can I edit it myself?', 'Yes. Every site comes with an admin panel, so you can update products, prices, text and images yourself, and you keep full control of the website.', 4);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('websites', 'What is an animated website?', 'A website where motion does the selling: scroll-driven product films, 3D, reveals and micro-interactions, like Firnlight, Oddball, Valmora and Earshot in our portfolio. They take longer to build than a standard site and start from $500.', 5);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('websites', 'Will my website show up on Google?', 'We build every site on fast, mobile-first foundations: clean page structure, titles and descriptions for each page, structured data, a sitemap and quick load times. Ranking also depends on your content and competition, and we''ll tell you what to focus on.', 6);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('apps', 'Do you build mobile apps?', 'Yes. We design and build mobile apps for iOS and Android, from the first screens to the admin side and publishing on the App Store and Google Play. Darebni AI, an AI-powered fitness app, is in development with us now.', 7);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('motion', 'What are motion graphics and content ads?', 'Short animated videos made for social media: reels, product ads, logo reveals, 3D pieces and kinetic typography, with sound designed to the picture. Every video in our motion section is our own work.', 8);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('motion', 'Which formats do you deliver for Instagram and TikTok?', 'Reels and TikTok in 9:16, feed posts in 4:5, and 16:9 for YouTube and websites, plus a silent version so you can add trending audio, and a cover image for your grid.', 9);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('ads', 'Is boosting a post the same as running Meta ads?', 'No. Boosting is one button with limited targeting. A campaign in Meta Ads Manager lets us choose the right objective, target and retarget audiences, test different creatives and track results. We set up and run those campaigns for you.', 10);
INSERT INTO faqs (topic, question, answer, sort) VALUES ('general', 'How do I book a call with Appify?', 'Use the booking form on this page: pick a day and time, choose what you need, and send it by WhatsApp or email. We reply to confirm.', 11);
INSERT INTO services (slug, name, h1, meta_title, meta_description, intro, points, related, faq_topic, sort) VALUES ('web-design-lebanon', 'Websites', 'Website design and development in Lebanon', 'Web Design in Lebanon | Websites from $360, $0/month | Appify', 'Appify designs and builds fast, animated websites and online stores in Lebanon: UI/UX, admin panel, analytics and free hosting. $360 lifetime, delivered in under 7 days.', 'We design and build websites and online stores that load fast, look like your brand and keep working without a monthly subscription. You get the design, the admin panel and the hosting for one price, delivered in under 7 days.', '[{"title": "UI/UX design", "text": "Pages designed around what your customers need to do, on phones first."}, {"title": "Admin panel", "text": "Update products, prices, text and images yourself, any time."}, {"title": "Custom analytics", "text": "See your visits, orders and what''s selling, without extra tools."}, {"title": "Free hosting, $0 per month", "text": "Pay once. No subscription to keep your site online."}, {"title": "Motion built in", "text": "Animated sections and product motion, or a fully animated site from $500."}, {"title": "Delivered in under 7 days", "text": "From the first call to a live website in a week."}]', 'websites', 'websites', 1);
INSERT INTO services (slug, name, h1, meta_title, meta_description, intro, points, related, faq_topic, sort) VALUES ('mobile-app-development-lebanon', 'Mobile apps', 'Mobile app development in Lebanon', 'Mobile App Development in Lebanon | iOS & Android | Appify', 'Appify designs and builds iOS and Android apps in Lebanon: UI/UX, the app, the admin side and App Store and Google Play publishing.', 'We turn app ideas into products people use: designed screen by screen, built for iOS and Android, with the admin side your team needs and the store listings handled for you.', '[{"title": "Product and UI/UX design", "text": "Flows and screens designed and tested before a line of code."}, {"title": "iOS and Android", "text": "One app, built for both stores."}, {"title": "Admin and backend", "text": "Manage users, content and data from a web dashboard."}, {"title": "Store publishing", "text": "App Store and Google Play listings, screenshots and review handled."}]', 'apps', 'apps', 2);
INSERT INTO services (slug, name, h1, meta_title, meta_description, intro, points, related, faq_topic, sort) VALUES ('motion-graphics-lebanon', 'Motion graphics', 'Motion graphics and content ads in Lebanon', 'Motion Graphics & Video Ads in Lebanon | Reels, 3D, Logo Reveals | Appify', 'Scroll-stopping motion graphics in Lebanon: Instagram and TikTok reels, product ads, 3D, logo reveals and kinetic typography, with sound designed to the picture.', 'Your brand has a second to stop the scroll. We make motion graphics that use it: reels, product ads, 3D pieces and logo reveals, timed to the beat and delivered in every format you post.', '[{"title": "Reels and TikToks", "text": "9:16 videos built around a hook in the first second."}, {"title": "Product and launch ads", "text": "Your product, your offer and your price, animated."}, {"title": "3D and logo reveals", "text": "Brand moments that make your logo memorable."}, {"title": "Sound design", "text": "Every hit has a sound, plus a silent cut for trending audio."}]', 'motion', 'motion', 3);
INSERT INTO services (slug, name, h1, meta_title, meta_description, intro, points, related, faq_topic, sort) VALUES ('meta-ads-lebanon', 'Meta ads', 'Meta ads management in Lebanon', 'Meta Ads in Lebanon | Facebook & Instagram Campaigns, Not Boosting | Appify', 'Appify runs Facebook and Instagram ad campaigns in Meta Ads Manager for Lebanese businesses: the right objective, targeting, retargeting and creatives that stop the scroll.', 'Boosting a post is not an ad strategy. We build and run campaigns in Meta Ads Manager, pairing the right objective and audience with motion creatives made to stop the scroll.', '[{"title": "The right objective", "text": "Messages, leads, sales or traffic, chosen for what you need."}, {"title": "Targeting and retargeting", "text": "Reach new people and bring back the ones who already looked."}, {"title": "Creative testing", "text": "Several ad versions, so the budget goes to what works."}, {"title": "Motion creatives", "text": "Ads made by the same team as our motion graphics."}]', 'motion', 'ads', 4);
